"},"$:/plugins/crosseye/json-convert/engine/convert.js":{"title":"$:/plugins/crosseye/json-convert/engine/convert.js","text":"const { prepareSource } = require('./prepare.js')
const { parsePath, resolvePath, renderPathSegments } = require('./path.js')
const { defaultTransforms, formatTwDate } = require('./transforms.js')
const { validateProfile } = require('./validate.js')
const { walkTemplate, parseToken, parseTransform } = require('./template.js')

const coerce = (v) =>
  typeof v === 'string' ? v
  : v === null || v === undefined ? ''
  : String(v)

// Resolve a token's path against the current record + ancestor stack.
// Leading `..` segments walk back through `ancestors` (innermost first);
// remaining segments resolve normally against the chosen scope.
// Returns the resolved value, or undefined if anything along the way
// is missing or the `..` count exceeds the available depth.
const resolveTokenPath = (segments, record, ancestors, context = {}) => {
  if (segments.length > 0 && segments[0].type === 'context') {
    const name = segments[0].name
    if (name === 'now') return context.now
    if (name === 'counter') return context.counter
    if (name === 'record') {
      const rest = segments.slice(1)
      return rest.length ? resolvePath(record, rest) : JSON.stringify(record)
    }
    return undefined
  }
  let i = 0
  let scope = record
  while (i < segments.length && segments[i].type === 'parent') {
    const upIdx = i  // 0 → ancestors[0] (innermost parent)
    if (upIdx >= ancestors.length) return undefined
    scope = ancestors[upIdx]
    i++
  }
  const remaining = segments.slice(i)
  if (remaining.length === 0) return scope
  return resolvePath(scope, remaining)
}

const interpolate = (
  template, record, recordIndex, transforms, ancestors = [], context = {}
) => {
  const warnings = []
  const out = []
  walkTemplate(template,
    () => {}, // malformed templates are caught by validate
    (text) => out.push(text),
    (content) => {
      const { path, transforms: tokenTransforms } = parseToken(content)
      const segments = parsePath(path)
      if (!segments) { out.push(''); return }
      let v = resolveTokenPath(segments, record, ancestors, context)
      if (v === undefined) {
        warnings.push({
          code: 'path-missing',
          message: `path "${path}" missing`,
          path,
          recordIndex
        })
        // Transforms still run, with an undefined value: that is how
        // `default[…]` supplies one, and the built-ins treat undefined
        // as empty.
        if (tokenTransforms.length === 0) {
          out.push('')
          return
        }
      }
      for (const spec of tokenTransforms) {
        const { name, params } = parseTransform(spec)
        const fn = transforms && transforms[name]
        // The validator has already checked the name is registered.
        if (fn) v = fn(v, params, { ...context, record })
      }
      out.push(coerce(v))
    }
  )
  return { value: out.join(''), warnings }
}

const evaluateBinding = (
  binding, record, recordIndex, transforms, ancestors = [], context = {}
) =>
  interpolate(binding, record, recordIndex, transforms, ancestors, context)

// Plain-language descriptions for diagnostics: what a value is, and
// where a records path stops matching the document.
const KEY_LIMIT = 12

const isPlainObject = (v) =>
  v !== null && typeof v === 'object' && !Array.isArray(v)

const describeValue = (v) => {
  if (v === undefined) return 'missing'
  if (v === null) return 'null'
  if (Array.isArray(v)) {
    return `an array of ${v.length} element${v.length === 1 ? '' : 's'}`
  }
  if (typeof v === 'object') {
    const keys = Object.keys(v)
    if (keys.length === 0) return 'an empty object'
    const shown = keys.slice(0, KEY_LIMIT).join(', ')
    const more = keys.length > KEY_LIMIT
      ? ` and ${keys.length - KEY_LIMIT} more`
      : ''
    return `an object with keys ${shown}${more}`
  }
  return `a ${typeof v}`
}

const describeKeys = (v) => {
  if (!isPlainObject(v)) return ''
  const keys = Object.keys(v)
  const shown = keys.slice(0, KEY_LIMIT).join(', ')
  return keys.length > KEY_LIMIT
    ? `${shown} and ${keys.length - KEY_LIMIT} more`
    : shown
}

const excerptOf = (v, limit = 160) => {
  let text
  try { text = JSON.stringify(v) } catch (_) { text = String(v) }
  if (text === undefined) text = String(v)
  return text.length > limit ? `${text.slice(0, limit - 1)}…` : text
}

// Walk a records path through the document and explain the first step
// that fails.  Returns null when every step resolves (the path is fine
// and merely empty).
const locateFailure = (root, segments) => {
  let node = root
  for (let i = 0; i < segments.length; i++) {
    const seg = segments[i]
    const at = i === 0 ? 'the document' : `"${renderPathSegments(segments.slice(0, i))}"`
    if (seg.type === 'key') {
      if (!isPlainObject(node) || !(seg.key in node)) {
        return isPlainObject(node)
          ? `${at} has no key "${seg.key}" (it is ${describeValue(node)})`
          : `${at} is ${describeValue(node)}, so it has no key "${seg.key}"`
      }
      node = node[seg.key]
    } else if (seg.type === 'index') {
      if (!Array.isArray(node) || seg.index >= node.length) {
        return `${at} is ${describeValue(node)}, so it has no element ${seg.index}`
      }
      node = node[seg.index]
    } else if (seg.type === 'star') {
      if (!Array.isArray(node)) {
        return `${at} is ${describeValue(node)}, not an array`
      }
      if (node.length === 0) return `${at} is an empty array`
      node = node[0]
    }
  }
  return null
}

const extractRecordsToken = (recordsPath) => {
  let path = null
  walkTemplate(recordsPath,
    () => {},
    () => {},
    (content) => { path = parseToken(content).path }
  )
  return path
}

// Walk the records path, branching at every `[*]`, and emit one
// {record, ancestors} per leaf reached.  ancestors[0] is the innermost
// parent scope (one `[*]` back); the deepest ancestor is the document
// root.  For records paths with no `[*]`, the resolved value (which
// must be an array) is iterated and each element is paired with
// ancestors=[root] for a consistent ancestry model.
const expandRecords = (root, recordsPath) => {
  const tokenPath = extractRecordsToken(recordsPath)
  const segments = parsePath(tokenPath)
  if (!segments) {
    return {
      records: null,
      error: {
        code: 'records-not-array',
        message:
          `records path "${recordsPath}" is not a valid path`,
        path: recordsPath
      }
    }
  }

  const hasAnyStar = segments.some((s) => s.type === 'star')
  if (!hasAnyStar) {
    const value = resolvePath(root, segments)
    if (!Array.isArray(value)) {
      const detail = locateFailure(root, segments) ||
        `it is ${describeValue(value)}`
      return {
        records: null,
        error: {
          code: 'records-not-array',
          message:
            `records path "${recordsPath}" did not resolve to an array: ` +
            detail,
          path: recordsPath,
          detail,
          document: describeValue(root)
        }
      }
    }
    return {
      records: value.map((r) => ({ record: r, ancestors: [root] })),
      error: null
    }
  }

  const records = []
  const walk = (node, i, recordStack) => {
    if (i >= segments.length) {
      const record = recordStack[recordStack.length - 1]
      const ancestors = recordStack.slice(0, -1).reverse()
      records.push({ record, ancestors })
      return
    }
    const seg = segments[i]
    if (seg.type === 'star') {
      if (!Array.isArray(node)) return
      for (const item of node) walk(item, i + 1, [...recordStack, item])
    } else if (seg.type === 'index') {
      if (!Array.isArray(node)) return
      walk(node[seg.index], i + 1, recordStack)
    } else if (seg.type === 'key') {
      if (typeof node !== 'object' || Array.isArray(node) || node === null) return
      walk(node[seg.key], i + 1, recordStack)
    }
  }
  walk(root, 0, [root])

  const detail = records.length === 0
    ? locateFailure(root, segments) || 'every array along it is empty'
    : null
  return { records, error: null, detail, document: describeValue(root) }
}

const convert = (jsonText, profile, existingTitles, options) => {
  const transforms = { ...defaultTransforms, ...options?.transforms }
  const existing = existingTitles || new Set()
  // Import-time context, the same for every record except the counter.
  // `options.now` lets a caller (or a test) fix the clock.
  const now = formatTwDate(options?.now || new Date())

  const profileErrors = validateProfile(profile, transforms)
  if (profileErrors.length > 0) {
    return {
      tiddlers: [],
      errors: profileErrors,
      warnings: [],
      collisions: new Set()
    }
  }

  const parsed = prepareSource(jsonText, profile.normalize)
  if (parsed.errors.length > 0) {
    return {
      tiddlers: [],
      errors: parsed.errors,
      warnings: parsed.warnings,
      collisions: new Set()
    }
  }
  const expanded = expandRecords(parsed.value, profile.records)
  if (expanded.error) {
    return {
      tiddlers: [],
      errors: [expanded.error],
      warnings: parsed.warnings,
      collisions: new Set()
    }
  }

  const warnings = parsed.warnings.slice()
  const errors = []
  const tiddlers = []
  const collisions = new Set()
  const seen = new Set()

  if (expanded.records.length === 0) {
    warnings.push({
      code: 'records-empty',
      message:
        `records path "${profile.records}" matched nothing: ` +
        expanded.detail +
        (expanded.detail.startsWith('the document')
          ? ''
          : `; the document is ${expanded.document}`),
      path: profile.records,
      detail: expanded.detail,
      document: expanded.document
    })
  }

  const titleBinding = typeof profile['tw-fields']?.title === 'string'
    ? profile['tw-fields'].title
    : typeof profile['custom-fields']?.title === 'string'
      ? profile['custom-fields'].title
      : ''

  expanded.records.forEach(({ record, ancestors }, recordIndex) => {
    const context = { now, counter: recordIndex + 1 }
    const fields = {}
    for (const [field, binding] of Object.entries(profile['tw-fields'] || {})) {
      const r = evaluateBinding(
        binding, record, recordIndex, transforms, ancestors, context
      )
      fields[field] = r.value
      warnings.push(...r.warnings)
    }
    for (const [field, binding] of Object.entries(profile['custom-fields'] || {})) {
      const r = evaluateBinding(
        binding, record, recordIndex, transforms, ancestors, context
      )
      fields[field] = r.value
      warnings.push(...r.warnings)
    }

    if (!fields.title) {
      const keys = describeKeys(record)
      errors.push({
        code: 'missing-title',
        message:
          `record ${recordIndex + 1} produced an empty title from ` +
          `"${titleBinding}"; the record ` +
          (keys ? `has keys ${keys}` : `is ${describeValue(record)}`),
        recordIndex,
        binding: titleBinding,
        keys,
        excerpt: excerptOf(record)
      })
      return
    }
    if (seen.has(fields.title)) {
      errors.push({
        code: 'duplicate-title',
        message: `title "${fields.title}" already produced in this batch`,
        recordIndex,
        title: fields.title
      })
      return
    }
    seen.add(fields.title)
    if (existing.has(fields.title)) {
      collisions.add(fields.title)
    }
    tiddlers.push(fields)
  })

  return { tiddlers, errors, warnings, collisions }
}

exports.interpolate = interpolate
exports.describeValue = describeValue
exports.locateFailure = locateFailure
exports.evaluateBinding = evaluateBinding
exports.expandRecords = expandRecords
exports.convert = convert
","type":"application/javascript","module-type":"library"},"$:/plugins/crosseye/json-convert/engine/drop.js":{"title":"$:/plugins/crosseye/json-convert/engine/drop.js","text":"const PROFILE_TAG = '$:/tags/json-convert/profile'

// What should a dropped tiddler do to the source box?
//
// A tiddler drag carries the whole tiddler as JSON, but the browser's
// default action for a textarea is to insert the drag's text/plain
// payload — which TiddlyWiki sets to the tiddler's title, bracketed
// when it contains spaces.  Dropping a profile on the source box
// therefore used to splice `[[Example Reified Output]]` into the JSON,
// producing a parse failure a dozen lines from where the eye looks for
// one.  Nothing dropped here may end up as a wikilink.

const TAG_RE = /\[\[[^\]]+\]\]|\S+/g

// Tags arrive as a TiddlyWiki list string or as an array, depending on
// whether the tiddler came from this wiki or across a drag.
const tagList = (tags) => {
  if (Array.isArray(tags)) return tags
  if (typeof tags !== 'string') return []
  return (tags.match(TAG_RE) || []).map((t) => t.replace(/^\[\[|\]\]$/g, ''))
}

const classifyDrop = (fields, profileExists) => {
  if (!fields || !fields.title) return { action: 'ignore' }
  if (tagList(fields.tags).indexOf(PROFILE_TAG) !== -1) {
    return profileExists
      ? { action: 'select-profile', title: fields.title }
      : {
          action: 'note',
          note: `"${fields.title}" is a profile from another wiki.  ` +
            'Drop it on the page background to import it first, then ' +
            'pick it from the profile list.'
        }
  }
  if (typeof fields.text === 'string' && fields.text.trim() !== '') {
    return { action: 'load-source', text: fields.text, title: fields.title }
  }
  return {
    action: 'note',
    note: `"${fields.title}" has no text to load as source JSON.`
  }
}

// TiddlyWiki puts the dragged tiddler's fields on the dataTransfer as
// `text/vnd.tiddler`; some browsers only get the data: URL form.
// Returns null when the payload isn't a tiddler at all.
const droppedTiddlerFields = (dataTransfer) => {
  if (!dataTransfer) return null
  const read = (type) => {
    try { return dataTransfer.getData(type) || '' } catch (_) { return '' }
  }
  let raw = read('text/vnd.tiddler')
  if (!raw) {
    const url = read('URL') || read('text/x-moz-url')
    const prefix = 'data:text/vnd.tiddler,'
    if (url.indexOf(prefix) === 0) {
      try {
        raw = decodeURIComponent(url.slice(prefix.length))
      } catch (_) {
        raw = ''
      }
    }
  }
  if (!raw) return null
  try {
    const parsed = JSON.parse(raw)
    const one = Array.isArray(parsed) ? parsed[0] : parsed
    return one && typeof one === 'object' && !Array.isArray(one) ? one : null
  } catch (_) {
    return null
  }
}

exports.classifyDrop = classifyDrop
exports.droppedTiddlerFields = droppedTiddlerFields
exports.tagList = tagList
exports.PROFILE_TAG = PROFILE_TAG
","type":"application/javascript","module-type":"library"},"$:/plugins/crosseye/json-convert/engine/field-name.js":{"title":"$:/plugins/crosseye/json-convert/engine/field-name.js","text":"const slugify = (s) => String(s).toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '')

// The key segments of a path, quoted ones unescaped, indices and stars
// dropped.  Used to derive field names, so only the words matter.
const splitPath = (path) => {
  const out = []
  const re = /\["((?:[^"\\]|\\.)*)"\]|([^.[\]]+)|\[([^\]]+)\]/g
  let m
  while ((m = re.exec(path)) !== null) {
    if (m[1] != null) {
      out.push(m[1].replace(/\\(.)/g, '$1'))
      continue
    }
    const seg = m[2] != null ? m[2] : m[3]
    if (seg !== '*' && seg !== '' && !/^\d+$/.test(seg)) out.push(seg)
  }
  return out
}

const withSuffix = (name, n) => n <= 1 ? name : `${name}-${n}`

const flattenPath = (path, takenNames) => {
  const segs = splitPath(path).map(slugify).filter((s) => s !== '')
  const taken = takenNames instanceof Set ? takenNames : new Set(takenNames || [])
  if (segs.length === 0) {
    for (let n = 1; n < 1000; n++) {
      const cand = withSuffix('field', n)
      if (!taken.has(cand)) return cand
    }
    return 'field'
  }
  for (let depth = 1; depth <= segs.length; depth++) {
    const base = segs.slice(segs.length - depth).join('-')
    if (!taken.has(base)) return base
  }
  const root = segs.join('-')
  for (let n = 2; n < 1000; n++) {
    const cand = withSuffix(root, n)
    if (!taken.has(cand)) return cand
  }
  return root
}

// Recognize a binding as a pass-through: returns the source path if the
// binding value is exactly `{{<path>}}` (no transforms, no extra text)
// AND <path> exists in the known leaf paths AND the field name is one
// the flattening rule could plausibly have produced for that path.
const passThroughPath = (bindingValue, fieldName, leafPaths) => {
  const m = /^\{\{([^|}]+)\}\}$/.exec(String(bindingValue || ''))
  if (!m) return null
  const path = m[1]
  const known = leafPaths instanceof Set ? leafPaths : new Set(leafPaths || [])
  if (!known.has(path)) return null
  const segs = splitPath(path).map(slugify).filter((s) => s !== '')
  if (segs.length === 0) {
    if (fieldName === 'field' || /^field-\d+$/.test(fieldName)) return path
    return null
  }
  for (let depth = 1; depth <= segs.length; depth++) {
    if (segs.slice(segs.length - depth).join('-') === fieldName) return path
  }
  const root = segs.join('-')
  if (fieldName.startsWith(root + '-')) {
    const tail = fieldName.slice(root.length + 1)
    if (/^\d+$/.test(tail)) return path
  }
  return null
}

exports.flattenPath = flattenPath
exports.passThroughPath = passThroughPath
exports.slugify = slugify
exports.splitPath = splitPath
","type":"application/javascript","module-type":"library"},"$:/plugins/crosseye/json-convert/engine/normalize.js":{"title":"$:/plugins/crosseye/json-convert/engine/normalize.js","text":"const { parsePath } = require('./path.js')

// Source normalization: reshape the parsed document *before* records
// expansion, so that inputs whose structure encodes what should be
// key/value pairs can be mapped with ordinary bindings.
//
// One step type exists, `pivot`.  It turns an array of entry-objects
//
//   [ {"key": "date", "value": "9/16/26"},
//     {"key": "total", "value": "42"} ]
//
// into the object those entries describe
//
//   {"date": "9/16/26", "total": "42"}
//
// In auto mode (no `at`) every array in the document that looks like
// entries is rewritten; `at` scopes the rewrite to one subtree.
// Values are carried over untouched — no stringification — so
// transforms still see numbers, booleans and nested structure.

const DEFAULT_KEY_FIELD = 'key'
const DEFAULT_VALUE_FIELD = 'value'
const STEP_NAMES = ['pivot']
const PIVOT_OPTIONS = ['key', 'value', 'at']

const isPlainObject = (v) =>
  v !== null && typeof v === 'object' && !Array.isArray(v)

const mapValues = (obj, fn) => {
  const out = {}
  for (const [k, v] of Object.entries(obj)) out[k] = fn(v)
  return out
}

// An entry carries a non-empty string key and *has* the value field.
// `vf in v` rather than a truthiness test: a null or empty value is
// still a field the source meant to report.
const isEntry = (v, kf, vf) =>
  isPlainObject(v) && typeof v[kf] === 'string' && v[kf] !== '' && vf in v

const isEntryArray = (v, kf, vf) =>
  Array.isArray(v) && v.length > 0 && v.every((e) => isEntry(e, kf, vf))

const pivotEntries = (arr, kf, vf, ctx) => {
  const out = {}
  for (const entry of arr) {
    if (entry[kf] in out) ctx.duplicates.add(entry[kf])
    out[entry[kf]] = entry[vf]
  }
  ctx.count++
  return out
}

// Rewrite everything at or below this node.  A pivoted result is
// walked again so nested reified structures collapse too.
const walk = (node, kf, vf, ctx) =>
  Array.isArray(node)
    ? isEntryArray(node, kf, vf)
      ? mapValues(pivotEntries(node, kf, vf, ctx), (v) => walk(v, kf, vf, ctx))
      : node.map((e) => walk(e, kf, vf, ctx))
    : isPlainObject(node)
      ? mapValues(node, (v) => walk(v, kf, vf, ctx))
      : node

// Descend along `at` without touching anything off the path; once the
// segments run out, hand the subtree to the auto walker.
const scoped = (node, segs, i, kf, vf, ctx) => {
  if (i >= segs.length) return walk(node, kf, vf, ctx)
  const seg = segs[i]
  const next = (child) => scoped(child, segs, i + 1, kf, vf, ctx)
  return seg.type === 'key'
    ? isPlainObject(node) && seg.key in node
      ? { ...node, [seg.key]: next(node[seg.key]) }
      : node
    : seg.type === 'index'
      ? Array.isArray(node) && seg.index < node.length
        ? node.map((e, j) => (j === seg.index ? next(e) : e))
        : node
      : seg.type === 'star'
        ? Array.isArray(node) ? node.map(next) : node
        : node // `..` is meaningless at document scope; validator rejects it
}

const quoteList = (items) => items.map((k) => `"${k}"`).join(', ')

const stepWarnings = (ctx, kf, vf) => {
  const warnings = []
  if (ctx.count === 0) {
    warnings.push({
      code: 'normalize-no-effect',
      message:
        'normalize: pivot found no key/value pair arrays to flatten ' +
        `(looking for objects with "${kf}" and "${vf}")`
    })
  }
  if (ctx.duplicates.size > 0) {
    warnings.push({
      code: 'normalize-duplicate-key',
      message:
        'normalize: pivot found repeated key(s) ' +
        `${quoteList([...ctx.duplicates])} within one group; ` +
        'the last value wins'
    })
  }
  return warnings
}

const applyStep = (doc, step, warnings) => {
  if (!isPlainObject(step) || !('pivot' in step)) return doc
  const opts = isPlainObject(step.pivot) ? step.pivot : {}
  const kf = typeof opts.key === 'string' && opts.key !== ''
    ? opts.key
    : DEFAULT_KEY_FIELD
  const vf = typeof opts.value === 'string' && opts.value !== ''
    ? opts.value
    : DEFAULT_VALUE_FIELD
  const segs = typeof opts.at === 'string' && opts.at !== ''
    ? parsePath(opts.at)
    : []
  if (segs === null) return doc // unparseable `at`; validator reports it
  const ctx = { count: 0, duplicates: new Set() }
  const value = scoped(doc, segs, 0, kf, vf, ctx)
  warnings.push(...stepWarnings(ctx, kf, vf))
  return value
}

// A spec arrives either as the profile's parsed `normalize` array or,
// from a widget attribute, as the JSON text of one.  Anything
// unrecognized normalizes to "do nothing" — validateProfile is what
// reports malformed specs to the user.
const parseSpec = (spec) => {
  if (Array.isArray(spec)) return spec.filter(isPlainObject)
  if (typeof spec !== 'string' || spec.trim() === '') return []
  try {
    const parsed = JSON.parse(spec)
    return Array.isArray(parsed) ? parsed.filter(isPlainObject) : []
  } catch (_) {
    return []
  }
}

const normalizeDoc = (doc, spec) => {
  const steps = parseSpec(spec)
  if (steps.length === 0) return { value: doc, warnings: [] }
  const warnings = []
  const value = steps.reduce(
    (acc, step) => applyStep(acc, step, warnings), doc
  )
  return { value, warnings }
}

// The spec the UI toggle writes: auto-detect, default field names.
const AUTO_PIVOT_SPEC = [{ pivot: {} }]

exports.normalizeDoc = normalizeDoc
exports.parseSpec = parseSpec
exports.isEntryArray = isEntryArray
exports.AUTO_PIVOT_SPEC = AUTO_PIVOT_SPEC
exports.DEFAULT_KEY_FIELD = DEFAULT_KEY_FIELD
exports.DEFAULT_VALUE_FIELD = DEFAULT_VALUE_FIELD
exports.STEP_NAMES = STEP_NAMES
exports.PIVOT_OPTIONS = PIVOT_OPTIONS
","type":"application/javascript","module-type":"library"},"$:/plugins/crosseye/json-convert/engine/parser.js":{"title":"$:/plugins/crosseye/json-convert/engine/parser.js","text":"const stripBOM = (s) =>
  s.charCodeAt(0) === 0xFEFF ? s.slice(1) : s

const findJsonSpan = (s) => {
  let start = -1
  for (let i = 0; i < s.length; i++) {
    const c = s[i]
    if (c === '{' || c === '[') {
      start = i
      break
    }
  }
  if (start < 0) return null

  let depth = 0
  let inString = false
  let escaped = false
  for (let i = start; i < s.length; i++) {
    const c = s[i]
    if (escaped) {
      escaped = false
      continue
    }
    if (inString) {
      if (c === '\\') escaped = true
      else if (c === '"') inString = false
      continue
    }
    if (c === '"') inString = true
    else if (c === '{' || c === '[') depth++
    else if (c === '}' || c === ']') {
      depth--
      if (depth === 0) return { start, end: i + 1 }
    }
  }
  return null
}

const NEWLINE = '\n'

// Where did it go wrong?  Every engine words this differently and some
// say nothing useful at all, so try each known shape and degrade to no
// location rather than to a wrong one:
//
//   V8/Node   ... at position 1684
//   V8 (newer)... at position 1684 (line 27 column 10)
//   SpiderMonkey  at line 27 column 10 of the JSON data
//   JavaScriptCore  (no location at all)
const extractLocation = (message, text) => {
  const lineCol = /at line (\d+) column (\d+)/.exec(message)
  if (lineCol) {
    return { line: Number(lineCol[1]), column: Number(lineCol[2]) }
  }
  const pos = /at position (\d+)/.exec(message)
  if (!pos) return {}
  const position = Number(pos[1])
  if (position > text.length) return {}
  const before = text.slice(0, position)
  const lineStart = before.lastIndexOf(NEWLINE) + 1
  return {
    position,
    line: before.split(NEWLINE).length,
    column: position - lineStart + 1
  }
}

// The offending line itself: "position 1684" tells you nothing when you
// are staring at a textarea.
const excerptFor = (text, line) => {
  if (line === undefined) return undefined
  const lines = text.split(NEWLINE)
  return line >= 1 && line <= lines.length ? lines[line - 1] : undefined
}

// The raw offset is reported in its own field, so keep it out of the
// prose.  The trailing snippet some engines append is noise too.
const tidyMessage = (message) => message
  .replace(/\s*(?:in JSON)?\s*at position \d+(?:\s*\(line \d+ column \d+\))?/, '')
  .replace(/\s*at line \d+ column \d+ of the JSON data/, '')
  .replace(/,?\s*(?:\.\.\.)?"[\s\S]*?"(?:\.\.\.)?\s*is not valid JSON/, '')
  .trim()

const parseError = (text, err) => {
  const { position, line, column } = extractLocation(err.message, text)
  const where = line === undefined ? '' : ` at line ${line}, column ${column}`
  return {
    code: 'parse-failed',
    message: `Malformed JSON${where}: ${tidyMessage(err.message)}`,
    position,
    line,
    column,
    excerpt: excerptFor(text, line)
  }
}

const tryParse = (text) => {
  try {
    return { ok: true, value: JSON.parse(text) }
  } catch (err) {
    return { ok: false, error: err }
  }
}

const recoveryNote = (text, stripped, span) => {
  const parts = []
  if (stripped.length < text.length) parts.push('BOM')
  if (span.start > 0 || span.end < stripped.length) {
    parts.push('non-JSON wrapper')
  }
  return parts.length
    ? `Parsed after stripping ${parts.join(' and ')}`
    : 'Parsed after recovery'
}

exports.parse = (text) => {
  const direct = tryParse(text)
  if (direct.ok) {
    return { value: direct.value, warnings: [], errors: [] }
  }

  const stripped = stripBOM(text)
  const span = findJsonSpan(stripped)
  if (span) {
    const slice = stripped.slice(span.start, span.end)
    const recovered = tryParse(slice)
    if (recovered.ok) {
      return {
        value: recovered.value,
        warnings: [{
          code: 'parse-recovered',
          message: recoveryNote(text, stripped, span)
        }],
        errors: []
      }
    }
  }

  return {
    value: undefined,
    warnings: [],
    errors: [parseError(text, direct.error)]
  }
}
