// Serializing a profile back to the JSON text of its tiddler.  Shared
// by the editor (which rebuilds the whole profile from its draft) and
// the console's normalize toggle (which changes one key and leaves
// the rest alone).

const KNOWN_KEYS = [
  'format', 'records', 'normalize', 'stamp', 'tw-fields', 'custom-fields'
]

const isPlainObject = (v) =>
  v !== null && typeof v === 'object' && !Array.isArray(v)

// One binding per line, colons aligned within each group.
const formatGroupBody = (group) => {
  const entries = Object.entries(group || {})
  if (entries.length === 0) return ''
  const keys = entries.map(([k]) => JSON.stringify(k))
  const maxKeyLen = Math.max(...keys.map((k) => k.length))
  return entries.map(([k, v]) => {
    const key = JSON.stringify(k)
    const pad = ' '.repeat(maxKeyLen - key.length + 1)
    return `    ${key}:${pad}${JSON.stringify(v)}`
  }).join(',\n')
}

const formatGroup = (name, group) => {
  const body = formatGroupBody(group)
  if (!body) return `  ${JSON.stringify(name)}: {}`
  return `  ${JSON.stringify(name)}: {\n${body}\n  }`
}

const formatProfile = (profile) => {
  const parts = []
  if (profile.format !== undefined) {
    parts.push(`  "format": ${JSON.stringify(profile.format)}`)
  }
  parts.push(`  "records": ${JSON.stringify(profile.records)}`)
  if (profile.normalize !== undefined) {
    parts.push(`  "normalize": ${JSON.stringify(profile.normalize)}`)
  }
  if (profile.stamp !== undefined) {
    parts.push(`  "stamp": ${JSON.stringify(profile.stamp)}`)
  }
  parts.push(formatGroup('tw-fields', profile['tw-fields']))
  if (profile['custom-fields'] !== undefined) {
    parts.push(formatGroup('custom-fields', profile['custom-fields']))
  }
  // Anything this tool doesn't know about is passed through rather
  // than dropped, so a rewrite never costs the user data.
  for (const [k, v] of Object.entries(profile)) {
    if (!KNOWN_KEYS.includes(k)) {
      parts.push(`  ${JSON.stringify(k)}: ${JSON.stringify(v)}`)
    }
  }
  return `{\n${parts.join(',\n')}\n}`
}

const normalizeEnabled = (profileText) => {
  try {
    const profile = JSON.parse(profileText)
    return isPlainObject(profile) &&
      Array.isArray(profile.normalize) &&
      profile.normalize.length > 0
  } catch (_) {
    return false
  }
}

// Turn the auto-pivot on or off in a profile's JSON text.  Returns
// null when the text isn't a profile object, so callers can leave a
// malformed profile untouched rather than overwrite it.  Turning it
// on preserves an existing hand-written spec; turning it off drops
// the key entirely.
const setNormalizeEnabled = (profileText, enabled) => {
  let profile
  try {
    profile = JSON.parse(profileText)
  } catch (_) {
    return null
  }
  if (!isPlainObject(profile)) return null
  if (!enabled) {
    if (profile.normalize === undefined) return null
    const { normalize, ...rest } = profile
    return formatProfile(rest)
  }
  if (Array.isArray(profile.normalize) && profile.normalize.length > 0) {
    return null
  }
  return formatProfile({ ...profile, normalize: AUTO_PIVOT_SPEC })
}

exports.formatProfile = formatProfile
exports.normalizeEnabled = normalizeEnabled
exports.setNormalizeEnabled = setNormalizeEnabled
","type":"application/javascript","module-type":"library"},"$:/plugins/crosseye/json-convert/engine/shape-diff.js":{"title":"$:/plugins/crosseye/json-convert/engine/shape-diff.js","text":"const { walkTemplate, parseToken } = require('./template.js')
const { parsePath, renderPathSegments } = require('./path.js')

// Shapes as engine/shape.js merges them, made JSON-safe and comparable.
// A pack records the serialized shape of the sample it was built
// against; at run time the same serialization of the recipient's
// records is compared with it, so the panel can say which fields the
// importer expected and did not find.

const serializeShape = (node) => {
  if (!node) return null
  const out = { kind: node.kind }
  if (node.presence) out.presence = node.presence
  if (node.kind === 'leaf') {
    out.types = [...(node.types || [])].sort()
  } else if (node.kind === 'object') {
    out.children = {}
    for (const key of Object.keys(node.children || {})) {
      out.children[key] = serializeShape(node.children[key])
    }
  } else if (node.kind === 'array' && node.element) {
    out.element = serializeShape(node.element)
  }
  return out
}

const join = (path, key) => (path ? `${path}.${key}` : key)

// missing: paths the expected shape has that the actual one lacks.
// added:   paths the actual shape has that the expected one lacks.
// changed: paths present in both whose kind or leaf type differs.
// A null value in the actual data never counts as a type change.
const compareShapes = (expected, actual) => {
  const diff = { missing: [], added: [], changed: [] }
  const walk = (e, a, path) => {
    if (!e || !a) return
    if (e.kind !== a.kind) {
      if (e.kind !== 'mixed' && a.kind !== 'mixed') {
        diff.changed.push({ path, expected: e.kind, actual: a.kind })
      }
      return
    }
    if (e.kind === 'leaf') {
      // A field that was null throughout the sample says nothing about
      // its type, so it cannot be contradicted.
      const et = (e.types || []).filter((t) => t !== 'null')
      const at = a.types || []
      const unexpected = at.filter((t) => t !== 'null' && !et.includes(t))
      if (et.length > 0 && unexpected.length > 0) {
        diff.changed.push({
          path, expected: et.join(' or '), actual: at.join(' or ')
        })
      }
      return
    }
    if (e.kind === 'object') {
      const ec = e.children || {}
      const ac = a.children || {}
      for (const key of Object.keys(ec)) {
        if (!(key in ac)) diff.missing.push(join(path, key))
        else walk(ec[key], ac[key], join(path, key))
      }
      for (const key of Object.keys(ac)) {
        if (!(key in ec)) diff.added.push(join(path, key))
      }
      return
    }
    if (e.kind === 'array' && e.element && a.element) {
      walk(e.element, a.element, `${path}[*]`)
    }
  }
  walk(expected, actual, '')
  return diff
}

const isMismatch = (diff) =>
  diff.missing.length > 0 || diff.changed.length > 0

// The record-relative paths a profile reads: every token path in its
// bindings, minus ancestor paths (`../x`, which are not in the record)
// and context paths other than `@record.x`, which is the record.
const profilePaths = (profile) => {
  const paths = new Set()
  const scan = (template) => {
    if (typeof template !== 'string') return
    walkTemplate(template, () => {}, () => {}, (content) => {
      const segs = parsePath(parseToken(content).path)
      if (!segs || segs.length === 0) return
      if (segs[0].type === 'parent') return
      if (segs[0].type === 'context') {
        if (segs[0].name !== 'record' || segs.length === 1) return
        paths.add(renderPathSegments(segs.slice(1)))
        return
      }
      paths.add(renderPathSegments(segs))
    })
  }
  for (const group of ['tw-fields', 'custom-fields']) {
    const bindings = profile && profile[group]
    if (bindings && typeof bindings === 'object') {
      Object.values(bindings).forEach(scan)
    }
  }
  return paths
}

// Keep only the differences that can affect the profile: a missing or
// changed path that some binding reads, or that a binding reads
// through.  Additions are kept as they are, being informational.
const relevantDiff = (diff, usedPaths) => {
  const used = [...usedPaths]
  const touches = (path) => used.some((u) =>
    u === path || u.startsWith(`${path}.`) || u.startsWith(`${path}[`)
  )
  return {
    missing: diff.missing.filter(touches),
    added: diff.added,
    changed: diff.changed.filter((c) => touches(c.path))
  }
}

// The field names at the top of a record shape, for messages.
const topLevelFields = (shape) =>
  shape && shape.kind === 'object' ? Object.keys(shape.children || {}) : []

exports.serializeShape = serializeShape
exports.compareShapes = compareShapes
exports.isMismatch = isMismatch
exports.profilePaths = profilePaths
exports.relevantDiff = relevantDiff
exports.topLevelFields = topLevelFields
","type":"application/javascript","module-type":"library"},"$:/plugins/crosseye/json-convert/engine/shape.js":{"title":"$:/plugins/crosseye/json-convert/engine/shape.js","text":"const DEFAULT_THRESHOLD = 10

const kindOf = (value) => {
  if (value === null) return 'leaf'
  if (Array.isArray(value)) return 'array'
  if (typeof value === 'object') return 'object'
  return 'leaf'
}

const typeOf = (value) => {
  if (value === null) return 'null'
  return typeof value
}

const bucket = (count, parentCount) => {
  if (count >= parentCount) return 'all'
  if (count === 1) return 'one'
  if (count >= parentCount / 2) return 'most'
  return 'some'
}

const presenceFor = (count, parentCount, inArray, trackPresence) => {
  if (inArray) return undefined
  if (!trackPresence) return 'all'
  return bucket(count, parentCount)
}

const leafNode = (values, inArray, presence) => {
  const types = new Set()
  let sampleValue
  let sampleSeen = false
  for (const v of values) {
    types.add(typeOf(v))
    if (!sampleSeen && v !== undefined) {
      sampleValue = v
      sampleSeen = true
    }
  }
  return {
    kind: 'leaf',
    inArray,
    presence,
    types,
    sampleValue
  }
}

const mergeAll = (values, inArray, parentCount, trackPresence) => {
  const presence = presenceFor(values.length, parentCount, inArray, trackPresence)

  const kinds = new Set()
  for (const v of values) kinds.add(kindOf(v))

  if (kinds.size > 1) {
    return { kind: 'mixed', inArray, presence }
  }

  const [kind] = [...kinds]

  if (kind === 'leaf') {
    return leafNode(values, inArray, presence)
  }

  if (kind === 'object') {
    const allKeys = new Set()
    for (const v of values) for (const k of Object.keys(v)) allKeys.add(k)
    const children = {}
    for (const key of allKeys) {
      const childValues = []
      for (const v of values) if (key in v) childValues.push(v[key])
      children[key] = mergeAll(childValues, inArray, values.length, trackPresence)
    }
    return { kind: 'object', inArray, presence, children }
  }

  // array
  const allElements = []
  for (const v of values) for (const e of v) allElements.push(e)
  const node = { kind: 'array', inArray, presence }
  if (allElements.length > 0) {
    node.element = mergeAll(allElements, true, allElements.length, trackPresence)
  }
  return node
}

const mergeRecordShapes = (records, opts = {}) => {
  if (!Array.isArray(records) || records.length === 0) return null
  const threshold = opts.threshold ?? DEFAULT_THRESHOLD
  const trackPresence = records.length >= threshold
  return mergeAll(records, false, records.length, trackPresence)
}

exports.mergeRecordShapes = mergeRecordShapes
exports.DEFAULT_THRESHOLD = DEFAULT_THRESHOLD
","type":"application/javascript","module-type":"library"},"$:/plugins/crosseye/json-convert/engine/template.js":{"title":"$:/plugins/crosseye/json-convert/engine/template.js","text":"// walkTemplate walks a binding template string, dispatching:
//   onText(string)  — for one or more literal characters
//   onToken(rawContent) — for the contents of a "{{...}}" token
//   onError({code, pos}) — when the template is malformed
//     codes: 'unterminated' (open "{{" with no matching "}}")
//
// Tokens are exactly `{{X}}` where X does not contain `}}`.
// Anything else — single braces included — is literal text.
//
// Token content is `path` or `path|t1|t2|...`; use parseToken to split.

const walkTemplate = (template, onError, onText, onToken) => {
  let i = 0
  while (i < template.length) {
    if (template[i] === '{' && template[i + 1] === '{') {
      let j = i + 2
      while (j < template.length - 1) {
        if (template[j] === '}' && template[j + 1] === '}') break
        j++
      }
      if (j >= template.length - 1) {
        onError({ code: 'unterminated', pos: i })
        return
      }
      onToken(template.slice(i + 2, j))
      i = j + 2
    } else {
      onText(template[i])
      i++
    }
  }
}

// Token content is `path` or `path|t1|t2|...`; each transform spec is
// a name optionally followed by bracketed parameters in TiddlyWiki's
// operand style: `zero-pad[3]`, `replace[from],[to]`.  A parameter
// cannot contain `]` (or `|`, which splits transforms).
const parseToken = (content) => {
  const parts = content.split('|')
  return { path: parts[0], transforms: parts.slice(1) }
}

const parseTransform = (spec) => {
  const open = spec.indexOf('[')
  if (open < 0) return { name: spec.trim(), params: [] }
  const name = spec.slice(0, open).trim()
  const params = []
  let rest = spec.slice(open)
  while (rest.length > 0) {
    if (rest[0] !== '[') return { name, params, error: 'malformed parameters' }
    const close = rest.indexOf(']')
    if (close < 0) return { name, params, error: 'unterminated parameter' }
    params.push(rest.slice(1, close))
    rest = rest.slice(close + 1)
    if (rest[0] === ',') rest = rest.slice(1)
    else if (rest.length > 0) return { name, params, error: 'malformed parameters' }
  }
  return { name, params }
}

exports.walkTemplate = walkTemplate
exports.parseToken = parseToken
exports.parseTransform = parseTransform
","type":"application/javascript","module-type":"library"},"$:/plugins/crosseye/json-convert/engine/transforms.js":{"title":"$:/plugins/crosseye/json-convert/engine/transforms.js","text":"const stringify = (v) =>
  v === null || v === undefined ? '' : String(v)

const htmlToWikitext = (v) => stringify(v)

const tiddlywikiList = (items) => items
  .filter((x) => x !== '')
  .map((x) => /\s/.test(x) ? `[[${x}]]` : x)
  .join(' ')

const splitOnCommas = (v) => Array.isArray(v)
  ? v.map((s) => stringify(s).trim())
  : stringify(v).split(',').map((s) => s.trim())

const splitCommas = (v) => tiddlywikiList(splitOnCommas(v))

const pad = (n, w) => String(n).padStart(w, '0')

const formatTwDate = (d) =>
  pad(d.getUTCFullYear(), 4) +
  pad(d.getUTCMonth() + 1, 2) +
  pad(d.getUTCDate(), 2) +
  pad(d.getUTCHours(), 2) +
  pad(d.getUTCMinutes(), 2) +
  pad(d.getUTCSeconds(), 2) +
  pad(d.getUTCMilliseconds(), 3)

const timestampToDate = (v) => {
  const n = Number(v)
  if (!Number.isFinite(n)) return ''
  const ms = n < 1e11 ? n * 1000 : n
  return formatTwDate(new Date(ms))
}

const isoToDate = (v) => {
  if (v === null || v === undefined || v === '') return ''
  const d = new Date(String(v))
  return Number.isNaN(d.getTime()) ? '' : formatTwDate(d)
}

// Parameterized built-ins.  Every transform is called as
// (value, params, context); these read params, the older ones ignore
// them.  Given the wrong parameters they leave the value alone.
const isEmpty = (v) => v === null || v === undefined || v === ''

const zeroPad = (v, params = []) => {
  const width = Number.parseInt(params[0], 10)
  if (!Number.isFinite(width) || width < 0) return v
  return stringify(v).padStart(width, '0')
}

const defaultTo = (v, params = []) =>
  isEmpty(v) ? (params[0] === undefined ? '' : params[0]) : v

const prefix = (v, params = []) =>
  isEmpty(v) || params[0] === undefined ? v : params[0] + stringify(v)

const suffix = (v, params = []) =>
  isEmpty(v) || params[0] === undefined ? v : stringify(v) + params[0]

const replace = (v, params = []) => {
  const from = params[0]
  if (from === undefined || from === '') return v
  return stringify(v).split(from).join(params[1] === undefined ? '' : params[1])
}

// An array of objects to the named property of each, as a TiddlyWiki
// title list (items with spaces double-bracketed), which is what a
// tags field wants.  A lone object yields its property; anything else
// yields ''.
const pluck = (v, params = []) => {
  const key = params[0]
  if (key === undefined) return v
  const items = Array.isArray(v) ? v : (v && typeof v === 'object' ? [v] : [])
  return tiddlywikiList(items.map((item) =>
    item && typeof item === 'object' ? stringify(item[key]) : ''
  ))
}

const defaultTransforms = {
  'html-to-wikitext':  htmlToWikitext,
  'split-commas':      splitCommas,
  'timestamp-to-date': timestampToDate,
  'iso-to-date':       isoToDate,
  'zero-pad':          zeroPad,
  'default':           defaultTo,
  'prefix':            prefix,
  'suffix':            suffix,
  'replace':           replace,
  'pluck':             pluck
}

exports.defaultTransforms = defaultTransforms
exports.formatTwDate = formatTwDate
","type":"application/javascript","module-type":"library"},"$:/plugins/crosseye/json-convert/engine/validate.js":{"title":"$:/plugins/crosseye/json-convert/engine/validate.js","text":"const {
  parsePath, hasStar, hasParent, parentCount, hasContext, CONTEXT_PATHS
} = require('./path.js')
const { STEP_NAMES, PIVOT_OPTIONS } = require('./normalize.js')
const { defaultTransforms } = require('./transforms.js')
const { walkTemplate, parseToken, parseTransform } = require('./template.js')

const isPlainObject = (v) =>
  v !== null && typeof v === 'object' && !Array.isArray(v)

const validateToken = (content, location, transformNames, recordsDepth) => {
  const errors = []
  const { path, transforms } = parseToken(content)
  if (path === '') {
    errors.push({
      code: 'binding-bad-token',
      message: `${location}: token "{{${content}}}" has empty path`,
      location
    })
    return errors
  }
  const segs = parsePath(path)
  if (segs === null) {
    errors.push({
      code: 'binding-bad-token',
      message: `${location}: token "{{${content}}}" is not a valid path` +
        (/@/.test(path)
          ? ' (a context path such as @now must be the whole path, ' +
            'with nothing before it)'
          : ''),
      location,
      path
    })
  } else {
    if (hasContext(segs)) {
      const name = segs[0].name
      if (!CONTEXT_PATHS.includes(name)) {
        errors.push({
          code: 'binding-bad-token',
          message: `${location}: token "{{${content}}}": unknown context ` +
            `path "@${name}"; the context paths are ` +
            CONTEXT_PATHS.map((n) => `@${n}`).join(', '),
          location,
          path
        })
      } else if (name !== 'record' && segs.length > 1) {
        errors.push({
          code: 'binding-bad-token',
          message: `${location}: token "{{${content}}}": @${name} takes ` +
            'no path after it',
          location,
          path
        })
      }
    }
    if (hasStar(segs)) {
      errors.push({
        code: 'binding-token-star',
        message: `${location}: [*] is not allowed in template tokens`,
        location,
        path
      })
    }
    const parents = parentCount(segs)
    if (parents > recordsDepth) {
      errors.push({
        code: 'binding-parent-too-deep',
        message:
          `${location}: token "{{${content}}}" steps up ${parents} ` +
          `ancestor(s), but the records path only provides ${recordsDepth}`,
        location,
        path
      })
    }
  }
  for (const spec of transforms) {
    const { name, error } = parseTransform(spec)
    if (name === '') {
      errors.push({
        code: 'binding-bad-token',
        message:
          `${location}: token "{{${content}}}" has empty transform name`,
        location
      })
    } else if (error) {
      errors.push({
        code: 'binding-bad-token',
        message:
          `${location}: token "{{${content}}}": ${error} in "${spec}" ` +
          '(parameters look like name[a] or name[a],[b])',
        location
      })
    } else if (!transformNames.has(name)) {
      errors.push({
        code: 'unknown-transform',
        message: `unknown transform "${name}" at ${location}`,
        location,
        transform: name
      })
    }
  }
  return errors
}

const validateTemplate = (template, location, transformNames, recordsDepth) => {
  const errors = []
  walkTemplate(template,
    (err) => {
      errors.push({
        code: 'binding-bad-token',
        message:
          `${location}: unterminated "{{" at position ${err.pos}`,
        location
      })
    },
    () => {},
    (content) => {
      errors.push(...validateToken(
        content, location, transformNames, recordsDepth
      ))
    }
  )
  return errors
}

const validateRecords = (records) => {
  if (typeof records !== 'string' || records === '') {
    return [{
      code: 'missing-records',
      message: 'profile.records must be a non-empty string'
    }]
  }
  let hasText = false
  let tokenCount = 0
  let tokenContent = null
  let walkErr = null
  walkTemplate(records,
    (err) => { walkErr = err },
    () => { hasText = true },
    (content) => { tokenCount++; tokenContent = content }
  )
  if (walkErr) {
    return [{
      code: 'bad-records-path',
      message:
        `profile.records: unterminated "{{" at position ${walkErr.pos}`,
      path: records
    }]
  }
  if (tokenCount !== 1 || hasText) {
    return [{
      code: 'bad-records-path',
      message:
        `profile.records "${records}" must be a single template ` +
        `token like "{{path}}" with no surrounding text`,
      path: records
    }]
  }
  const { path, transforms } = parseToken(tokenContent)
  if (transforms.length > 0) {
    return [{
      code: 'bad-records-path',
      message:
        `profile.records "${records}" cannot contain transforms`,
      path: records
    }]
  }
  const segs = parsePath(path)
  if (segs === null) {
    return [{
      code: 'bad-records-path',
      message:
        `profile.records token "{{${tokenContent}}}" is not a valid path`,
      path
    }]
  }
  if (hasParent(segs)) {
    return [{
      code: 'bad-records-path',
      message:
        `profile.records "${records}" cannot use ".." (ancestor scopes are only valid in bindings)`,
      path
    }]
  }
  return []
}

// How many ancestor scopes does this records path provide to its
// bindings?  Each `[*]` adds one level; paths with no `[*]` still
// expose the document root (1 level).
const computeRecordsDepth = (records) => {
  if (typeof records !== 'string') return 1
  let count = 0
  let walkErr = null
  walkTemplate(records,
    (err) => { walkErr = err },
    () => {},
    (content) => {
      const segs = parsePath(parseToken(content).path)
      if (segs) for (const s of segs) if (s.type === 'star') count++
    }
  )
  if (walkErr) return 1
  return Math.max(count, 1)
}

const validateBinding = (binding, location, transformNames, recordsDepth) => {
  if (typeof binding !== 'string') {
    return [{
      code: 'binding-bad-shape',
      message: `${location} must be a string`,
      location
    }]
  }
  return validateTemplate(
    binding, location, transformNames,
    recordsDepth === undefined ? Infinity : recordsDepth
  )
}

const validateCustomFields = (
  customFields, twFields, transformNames, recordsDepth
) => {
  if (!isPlainObject(customFields)) {
    return [{
      code: 'custom-fields-not-object',
      message: 'profile.custom-fields must be an object'
    }]
  }
  const errors = []
  const twKeys = isPlainObject(twFields)
    ? new Set(Object.keys(twFields))
    : new Set()
  for (const [field, binding] of Object.entries(customFields)) {
    const location = `custom-fields.${field}`
    if (twKeys.has(field)) {
      errors.push({
        code: 'field-redefined',
        message: `${location} is already defined in tw-fields`,
        location,
        field
      })
    }
    errors.push(...validateBinding(
      binding, location, transformNames, recordsDepth
    ))
  }
  return errors
}

// profile.normalize is an optional list of reshaping steps applied to
// the source document before records expansion.  One step type is
// recognized: {"pivot": {key?, value?, at?}}.
const validatePivot = (opts, location) => {
  if (!isPlainObject(opts)) {
    return [{
      code: 'normalize-bad-step',
      message: `${location}: "pivot" must be an object`,
      location
    }]
  }
  const errors = []
  for (const name of Object.keys(opts)) {
    if (!PIVOT_OPTIONS.includes(name)) {
      errors.push({
        code: 'normalize-bad-step',
        message:
          `${location}: unknown pivot option "${name}" ` +
          `(expected ${PIVOT_OPTIONS.join(', ')})`,
        location
      })
    } else if (typeof opts[name] !== 'string') {
      errors.push({
        code: 'normalize-bad-step',
        message: `${location}: pivot "${name}" must be a string`,
        location
      })
    }
  }
  if (typeof opts.at === 'string' && opts.at !== '') {
    const segs = parsePath(opts.at)
    if (segs === null) {
      errors.push({
        code: 'normalize-bad-step',
        message: `${location}: pivot "at" is not a valid path`,
        location,
        path: opts.at
      })
    } else if (hasParent(segs)) {
      errors.push({
        code: 'normalize-bad-step',
        message:
          `${location}: pivot "at" cannot use ".." — it is resolved ` +
          'against the whole document',
        location,
        path: opts.at
      })
    }
  }
  return errors
}

const validateNormalize = (normalize) => {
  if (normalize === undefined) return []
  if (!Array.isArray(normalize)) {
    return [{
      code: 'normalize-not-array',
      message: 'profile.normalize must be an array of steps'
    }]
  }
  const errors = []
  normalize.forEach((step, i) => {
    const location = `normalize[${i}]`
    if (!isPlainObject(step)) {
      errors.push({
        code: 'unknown-normalize-step',
        message: `${location} must be an object like {"pivot": {}}`,
        location
      })
      return
    }
    const names = Object.keys(step)
    if (names.length !== 1 || !STEP_NAMES.includes(names[0])) {
      errors.push({
        code: 'unknown-normalize-step',
        message:
          `${location}: expected exactly one of ${STEP_NAMES.join(', ')}, ` +
          `got ${names.length === 0 ? '{}' : names.map((n) => `"${n}"`).join(', ')}`,
        location
      })
      return
    }
    errors.push(...validatePivot(step.pivot, location))
  })
  return errors
}

// Profile format versions this engine reads.  A profile may carry an
// integer `format` key (absent means 1); the studio stamps it when it
// generates a pack, so a runtime that has dropped a format can say so
// instead of misreading the profile.
const SUPPORTED_FORMATS = [1]

const validateFormat = (format) => {
  if (format === undefined || SUPPORTED_FORMATS.includes(format)) return []
  return [{
    code: 'unsupported-format',
    message:
      `profile.format ${JSON.stringify(format)} is not supported; ` +
      `this runtime reads format ${SUPPORTED_FORMATS.join(', ')} — ` +
      'regenerate the profile in the studio'
  }]
}

// Fields Apply fills in when the profile does not bind them.  Absent
// means created and modified, as TiddlyWiki stamps any new tiddler; an
// empty list opts out; creator and modifier are opt-in.
const STAMP_FIELDS = ['created', 'modified', 'creator', 'modifier']
const DEFAULT_STAMP = ['created', 'modified']

const validateStamp = (stamp) => {
  if (stamp === undefined) return []
  if (!Array.isArray(stamp)) {
    return [{
      code: 'bad-stamp',
      message: `profile.stamp must be a list of field names ` +
        `(${STAMP_FIELDS.join(', ')})`
    }]
  }
  return stamp
    .filter((name) => !STAMP_FIELDS.includes(name))
    .map((name) => ({
      code: 'bad-stamp',
      message: `profile.stamp: ${JSON.stringify(name)} is not a field ` +
        `Apply can stamp (${STAMP_FIELDS.join(', ')})`
    }))
}

// The resolved list for a profile, default applied.
const stampFields = (profile) =>
  profile && Array.isArray(profile.stamp)
    ? profile.stamp.filter((name) => STAMP_FIELDS.includes(name))
    : DEFAULT_STAMP.slice()

// The records path may not be a context path: there is no record yet.
const validateRecordsContext = (records) => {
  if (typeof records !== 'string') return []
  let tokenPath = null
  walkTemplate(records, () => {}, () => {}, (content) => {
    if (tokenPath === null) tokenPath = parseToken(content).path
  })
  const segs = tokenPath === null ? null : parsePath(tokenPath)
  if (!segs || !hasContext(segs)) return []
  return [{
    code: 'bad-records-path',
    message: `profile.records "${records}" cannot be a context path; ` +
      'context paths describe the record being converted',
    path: records
  }]
}

const validateProfile = (profile, transforms) => {
  if (!isPlainObject(profile)) {
    return [{
      code: 'profile-not-object',
      message: 'profile must be an object'
    }]
  }

  const errors = []
  errors.push(...validateFormat(profile.format))
  errors.push(...validateStamp(profile.stamp))
  const transformNames = new Set(
    Object.keys({ ...defaultTransforms, ...transforms })
  )

  errors.push(...validateRecords(profile.records))
  errors.push(...validateRecordsContext(profile.records))
  errors.push(...validateNormalize(profile.normalize))

  const recordsDepth = computeRecordsDepth(profile.records)

  const twFields = profile['tw-fields']
  if (twFields === undefined) {
    errors.push({
      code: 'missing-title-binding',
      message: 'profile.tw-fields must include "title"'
    })
  } else if (!isPlainObject(twFields)) {
    errors.push({
      code: 'tw-fields-not-object',
      message: 'profile.tw-fields must be an object'
    })
  } else {
    if (!('title' in twFields)) {
      errors.push({
        code: 'missing-title-binding',
        message: 'profile.tw-fields must include "title"'
      })
    }
    for (const [field, binding] of Object.entries(twFields)) {
      errors.push(
        ...validateBinding(
          binding, `tw-fields.${field}`, transformNames, recordsDepth
        )
      )
    }
  }

  if ('custom-fields' in profile) {
    errors.push(
      ...validateCustomFields(
        profile['custom-fields'], twFields, transformNames, recordsDepth
      )
    )
  }

  return errors
}

exports.validateProfile = validateProfile
exports.SUPPORTED_FORMATS = SUPPORTED_FORMATS
exports.STAMP_FIELDS = STAMP_FIELDS
exports.DEFAULT_STAMP = DEFAULT_STAMP
exports.stampFields = stampFields
exports.validateNormalize = validateNormalize
exports.validateBinding = validateBinding
exports.validateTemplate = validateTemplate
","type":"application/javascript","module-type":"library"},"$:/plugins/crosseye/json-convert/filters/normalize-enabled.js":{"title":"$:/plugins/crosseye/json-convert/filters/normalize-enabled.js","text":"const { normalizeEnabled } = require(
  '$:/plugins/crosseye/json-convert/engine/profile-format.js'
)

// For each input profile title, emit "yes" when that profile carries a
// non-empty `normalize` spec, "no" otherwise.  Lets the console read
// the flatten setting straight out of the profile — no mirrored state
// tiddler to drift.  Intended use:
//
//   [<profile>jc-normalize-enabled[]match[yes]]
exports['jc-normalize-enabled'] = function(source) {
  const out = []
  source((tiddler, title) => {
    const text = tiddler ? tiddler.fields.text || '' : ''
    out.push(normalizeEnabled(text) ? 'yes' : 'no')
  })
  return out
}
","type":"application/javascript","module-type":"filteroperator"},"$:/plugins/crosseye/json-convert/filters/transform-name.js":{"title":"$:/plugins/crosseye/json-convert/filters/transform-name.js","text":"const {
  transformName,
  TRANSFORM_TYPES
} = require('$:/plugins/crosseye/json-convert/widgets/util.js')

// For each input tiddler in the source list, emit its transform name
// (the `name` field, defaulting to a slug of the title).  Tiddlers
// whose type isn't a recognised transform body language are skipped.
// Intended use:
//
//   [tag[$:/tags/json-convert/transform]jc-transform-name[]]
exports['jc-transform-name'] = function(source) {
  const out = []
  source((tiddler, title) => {
    if (!tiddler) return
    if (!TRANSFORM_TYPES.has(tiddler.fields.type)) return
    const name = transformName(tiddler, title)
    if (name) out.push(name)
  })
  return out
}
