"},"$:/plugins/crosseye/json-convert/usage":{"title":"$:/plugins/crosseye/json-convert/usage","caption":"Usage","text":"! Using an importer

An //importer// is a small plugin somebody built for one kind of JSON —
invoices, a reading list, a course export — and gave to you.  It adds a
page named for that data, listed under ''More › Importers'' in the
sidebar and linked from the plugin's own readme.  Everything about
//how// the JSON turns into tiddlers was decided when the importer was
made; your part is four steps.

# ''Get the JSON in.''  Paste it into the ''Source JSON'' box, drop the file on the box, or use the file chooser beside it; ''Clear'' empties the box when you are done with a batch.  A status line under the box tells you at once whether the text is valid JSON, and if not, where it goes wrong.  If the importer ships a sample, ''Try it with the sample'' loads one so you can watch the whole thing work first.
# ''Convert.''  The big green button (it may be labelled for the data, e.g. ''Stage books'') runs the conversion.  Nothing is written to the wiki yet.  The ''Results'' table counts what was produced and lists any errors, warnings and title collisions.
# ''Review.''  The ''Staging'' list shows every tiddler about to be written.  Expand a row to see its fields and text.  Titles that already exist in the wiki appear under ''Conflicts'': choose ''skip'', ''overwrite'' or ''rename'' for each, or set them all at once.  New titles default to ''add''.
# ''Apply.''  Writes the tiddlers you kept, dated to the moment of import unless the importer set the dates from the data, then clears the staging area.  ''Imported this session'' lists what was written, with links, until you reload.  ''Cancel'' throws the staged tiddlers away instead.

!! Where things go

The importer keeps its working data — the pasted text, the results, the
staged tiddlers and the session list — under `$:/temp/json-convert/`
followed by the importer's own name.  Nothing there is saved with the
wiki, and two importers in one wiki never see each other's data.  Only
''Apply'' writes ordinary tiddlers.

!! What you cannot change here

The profile (which fields become which), any input flattening, and the
default action for a title collision are fixed inside the importer.
That is the point: the person who built it did the hard part once.

!! When it does not fit

An importer is built for one shape of JSON.  When yours differs, the
''Results'' panel says so in plain words rather than staging nothing
quietly:

* ''Nothing was staged'' names the step of the records path that matched nothing, and what the document had there instead.
* ''Empty titles'' says which binding produced them and what the first such record looked like.
* ''This JSON doesn't look like what this importer expects'' lists the fields the importer was built for that your records lack, and any whose type changed, when the importer ships a sample to compare against.

Each of these ends with the same sentence: if your JSON is what it
should be, the importer's profile needs updating by whoever made it, and
the panel links to the studio it came from.  There is nothing to fix on
your side.

!! Building your own

The [[JSON Convert Studio|$:/plugins/crosseye/json-convert-studio]]
plugin adds the Console, a form-based profile editor with pickers, and
the full reference guide.  Install it alongside this runtime to write
profiles and, in due course, generate importers of your own.
"},"$:/plugins/crosseye/json-convert/widgets/apply.js":{"title":"$:/plugins/crosseye/json-convert/widgets/apply.js","text":"const Widget = require('$:/core/modules/widgets/widget.js').widget
const { clearByPrefix } = require('./util.js')

const DEFAULT_STATE_BASE  = '$:/state/json-convert'
const DEFAULT_STAGED_BASE = '$:/temp/json-convert/staged'

const META_FIELDS = new Set(['title', '_target-title', '_collision', '_stamp'])
const CREATION_FIELDS = new Set(['created', 'creator'])

const stripMeta = (fields) => {
  const out = {}
  for (const k of Object.keys(fields)) {
    if (!META_FIELDS.has(k)) out[k] = fields[k]
  }
  return out
}

const stagedTitles = (wiki, prefix) => {
  const titles = []
  wiki.each((tiddler, title) => {
    if (title.indexOf(prefix) === 0) titles.push(title)
  })
  return titles
}

const recordImports = (wiki, auditTitle, importedTitles) => {
  if (importedTitles.length === 0) return
  const existing = wiki.getTiddler(auditTitle)
  const prior = existing
    ? $tw.utils.parseStringArray(existing.fields.list || '')
    : []
  const seen = new Set(prior)
  const next = [...prior]
  for (const t of importedTitles) {
    if (!seen.has(t)) { next.push(t); seen.add(t) }
  }
  wiki.addTiddler({
    title: auditTitle,
    list: $tw.utils.stringifyList(next)
  })
}

const applyOne = (wiki, stagedTitle, stagedPrefix, decisionsPrefix) => {
  const i = stagedTitle.slice(stagedPrefix.length)
  const decision = wiki.getTiddler(`${decisionsPrefix}${i}`)
  const action = decision?.fields.text || 'skip'
  if (action === 'skip') return null

  const staged = wiki.getTiddler(stagedTitle)
  if (!staged) return null

  const targetTitle = action === 'rename'
    ? (decision.fields['rename-title'] || '').trim()
    : staged.fields['_target-title']
  if (!targetTitle) return null

  const fields = stripMeta(staged.fields)
  const existing = wiki.getTiddler(targetTitle)

  // A merge never changes when or by whom a tiddler was created; only
  // a value the profile bound does, because then the author asked.
  if (existing) {
    for (const name of CREATION_FIELDS) {
      if (fields[name] === undefined && existing.fields[name] !== undefined) {
        fields[name] = existing.fields[name]
      }
    }
  }

  // Fill the fields the profile asked to have stamped, where it did
  // not bind them itself and the merge above did not keep them.
  const stamps = $tw.utils.parseStringArray(staged.fields._stamp || '')
  if (stamps.length) {
    const creation = wiki.getCreationFields()
    const modification = wiki.getModificationFields()
    for (const name of stamps) {
      if (fields[name] !== undefined) continue
      const source = CREATION_FIELDS.has(name) ? creation : modification
      if (source[name] !== undefined) fields[name] = source[name]
    }
  }

  wiki.addTiddler({ ...fields, title: targetTitle })
  return targetTitle
}

const applyAll = (wiki, stateBase, stagedBase, auditTitle) => {
  const stagedPrefix    = `${stagedBase}/`
  const decisionsPrefix = `${stateBase}/decisions/`
  const imported = stagedTitles(wiki, stagedPrefix)
    .map((t) => applyOne(wiki, t, stagedPrefix, decisionsPrefix))
    .filter((t) => t !== null)
  recordImports(wiki, auditTitle, imported)
  clearByPrefix(wiki, stagedPrefix)
  clearByPrefix(wiki, decisionsPrefix)
}

const JsonConvertApplyWidget = function(parseTreeNode, options) {
  this.initialise(parseTreeNode, options)
}

JsonConvertApplyWidget.prototype = Object.create(Widget.prototype)

JsonConvertApplyWidget.prototype.render = function(parent, nextSibling) {
  this.computeAttributes()
  this.execute()
}

JsonConvertApplyWidget.prototype.execute = function() {
  this.stateBase  = this.getAttribute('state-base',  DEFAULT_STATE_BASE)
  this.stagedBase = this.getAttribute('staged-base', DEFAULT_STAGED_BASE)
  this.auditTitle =
    this.getAttribute('audit-title', `${this.stateBase}/audit-log`)
}

JsonConvertApplyWidget.prototype.refresh = function() {
  const changed = this.computeAttributes()
  if (changed['state-base'] || changed['staged-base'] ||
      changed['audit-title']) {
    this.refreshSelf()
    return true
  }
  return false
}

JsonConvertApplyWidget.prototype.invokeAction = function() {
  applyAll(this.wiki, this.stateBase, this.stagedBase, this.auditTitle)
  return true
}

exports['json-convert-apply'] = JsonConvertApplyWidget
","type":"application/javascript","module-type":"widget"},"$:/plugins/crosseye/json-convert/widgets/browse-file.js":{"title":"$:/plugins/crosseye/json-convert/widgets/browse-file.js","text":"const Widget = require('$:/core/modules/widgets/widget.js').widget

const writeText = (wiki, title, text) => {
  const existing = wiki.getTiddler(title)
  const fields = existing ? { ...existing.fields } : {}
  fields.title = title
  fields.text = text
  wiki.addTiddler(fields)
}

function JsonConvertBrowseFileWidget(parseTreeNode, options) {
  this.initialise(parseTreeNode, options)
}

JsonConvertBrowseFileWidget.prototype = Object.create(Widget.prototype)

JsonConvertBrowseFileWidget.prototype.render = function(parent, nextSibling) {
  this.parentDomNode = parent
  this.computeAttributes()
  this.execute()

  const input = this.document.createElement('input')
  input.type = 'file'
  input.accept = this.accept
  if (this.inputClass) input.className = this.inputClass

  input.addEventListener('change', () => {
    const file = input.files && input.files[0]
    if (!file) return
    const reader = new FileReader()
    reader.onload = () => {
      writeText(this.wiki, this.targetTitle, String(reader.result || ''))
      if (this.actions) {
        this.invokeActionString(this.actions, this, null, {})
      }
      input.value = '' // allow reselecting the same file
    }
    reader.onerror = () => {
      console.error('[jc-browse-file] read failed:', reader.error)
    }
    reader.readAsText(file)
  })

  parent.insertBefore(input, nextSibling)
  this.domNodes.push(input)
}

JsonConvertBrowseFileWidget.prototype.execute = function() {
  this.targetTitle = this.getAttribute('target-title', '')
  this.accept = this.getAttribute('accept', '.json,application/json,.txt,text/plain')
  this.inputClass = this.getAttribute('class', '')
  this.actions = this.getAttribute('actions', '')
}

JsonConvertBrowseFileWidget.prototype.refresh = function(changedTiddlers) {
  const changed = this.computeAttributes()
  if (changed['target-title'] || changed.accept ||
      changed.class || changed.actions) {
    this.refreshSelf()
    return true
  }
  return false
}

exports['json-convert-browse-file'] = JsonConvertBrowseFileWidget
","type":"application/javascript","module-type":"widget"},"$:/plugins/crosseye/json-convert/widgets/drop-file.js":{"title":"$:/plugins/crosseye/json-convert/widgets/drop-file.js","text":"const Widget = require('$:/core/modules/widgets/widget.js').widget
const { classifyDrop, droppedTiddlerFields } = require(
  '$:/plugins/crosseye/json-convert/engine/drop.js'
)

const writeText = (wiki, title, text) => {
  const existing = wiki.getTiddler(title)
  const fields = existing ? { ...existing.fields } : {}
  fields.title = title
  fields.text = text
  wiki.addTiddler(fields)
}

const hasTiddler = (e) => {
  if (!e.dataTransfer) return false
  const types = e.dataTransfer.types
  if (!types) return false
  for (let i = 0; i < types.length; i++) {
    if (types[i] === 'text/vnd.tiddler' || types[i] === 'URL') return true
  }
  return false
}

const hasFile = (e) => {
  if (!e.dataTransfer) return false
  const types = e.dataTransfer.types
  if (!types) return false
  for (let i = 0; i < types.length; i++) {
    if (types[i] === 'Files') return true
  }
  return false
}

function JsonConvertDropFileWidget(parseTreeNode, options) {
  this.initialise(parseTreeNode, options)
}

JsonConvertDropFileWidget.prototype = Object.create(Widget.prototype)

JsonConvertDropFileWidget.prototype.render = function(parent, nextSibling) {
  this.parentDomNode = parent
  this.computeAttributes()
  this.execute()

  const wrapper = this.document.createElement('div')
  wrapper.className = this.wrapperClass

  this.renderChildren(wrapper, null)

  let depth = 0
  const setActive = (on) => {
    if (on) wrapper.classList.add('jc-dropzone-active')
    else wrapper.classList.remove('jc-dropzone-active')
  }

  // Capturing-phase listeners so we run before any descendant default
  // and before TW's body-level import handler can see the event.
  wrapper.addEventListener('dragenter', (e) => {
    if (!hasFile(e) && !hasTiddler(e)) return
    e.preventDefault()
    e.stopPropagation()
    depth++
    setActive(true)
  }, true)

  wrapper.addEventListener('dragover', (e) => {
    if (!hasFile(e) && !hasTiddler(e)) return
    e.preventDefault()
    e.stopPropagation()
    e.dataTransfer.dropEffect = 'copy'
  }, true)

  wrapper.addEventListener('dragleave', (e) => {
    if (!hasFile(e) && !hasTiddler(e)) return
    e.preventDefault()
    e.stopPropagation()
    depth--
    if (depth <= 0) {
      depth = 0
      setActive(false)
    }
  }, true)

  wrapper.addEventListener('drop', (e) => {
    if (!hasFile(e) && !hasTiddler(e)) return
    e.preventDefault()
    e.stopPropagation()
    depth = 0
    setActive(false)

    if (!hasFile(e)) {
      this.handleTiddlerDrop(droppedTiddlerFields(e.dataTransfer))
      return
    }
    this.setNote('')

    const file = e.dataTransfer.files && e.dataTransfer.files[0]
    if (!file) return
    const reader = new FileReader()
    reader.onload = () => {
      writeText(this.wiki, this.targetTitle, String(reader.result || ''))
      if (this.actions) {
        this.invokeActionString(this.actions, this, null, {})
      }
    }
    reader.onerror = () => {
      console.error('[jc-drop-file] read failed:', reader.error)
    }
    reader.readAsText(file)
  }, true)

  parent.insertBefore(wrapper, nextSibling)
  this.domNodes.push(wrapper)
}

// A dropped tiddler never becomes text in the box: a profile selects
// itself, anything else loads its text as the source.
JsonConvertDropFileWidget.prototype.handleTiddlerDrop = function(fields) {
  const title = fields && fields.title
  const exists = !!(title && this.wiki.tiddlerExists(title))
  const outcome = classifyDrop(fields, exists)
  if (outcome.action === 'select-profile' && this.profileTitle) {
    writeText(this.wiki, this.profileTitle, outcome.title)
    this.setNote(`Selected profile "${outcome.title}".`)
    return
  }
  if (outcome.action === 'load-source') {
    writeText(this.wiki, this.targetTitle, outcome.text)
    this.setNote(`Loaded source JSON from "${outcome.title}".`)
    if (this.actions) this.invokeActionString(this.actions, this, null, {})
    return
  }
  if (outcome.action === 'note') this.setNote(outcome.note)
}

JsonConvertDropFileWidget.prototype.setNote = function(note) {
  if (!this.noteTitle) return
  if (note) writeText(this.wiki, this.noteTitle, note)
  else this.wiki.deleteTiddler(this.noteTitle)
}

JsonConvertDropFileWidget.prototype.execute = function() {
  this.targetTitle = this.getAttribute('target-title', '')
  this.profileTitle = this.getAttribute('profile-title', '')
  this.noteTitle = this.getAttribute('note-title', '')
  this.wrapperClass = this.getAttribute('class', 'jc-dropzone')
  this.actions = this.getAttribute('actions', '')
  this.makeChildWidgets()
}

JsonConvertDropFileWidget.prototype.refresh = function(changedTiddlers) {
  const changed = this.computeAttributes()
  if (changed['target-title'] || changed.class || changed.actions ||
      changed['profile-title'] || changed['note-title']) {
    this.refreshSelf()
    return true
  }
  return this.refreshChildren(changedTiddlers)
}

exports['json-convert-drop-file'] = JsonConvertDropFileWidget
