","type":"application/javascript","module-type":"widget"},"$:/plugins/crosseye/json-convert/widgets/run.js":{"title":"$:/plugins/crosseye/json-convert/widgets/run.js","text":"const Widget = require('$:/core/modules/widgets/widget.js').widget
const { convert, expandRecords } = require(
  '$:/plugins/crosseye/json-convert/engine/convert.js'
)
const { prepareSource } = require(
  '$:/plugins/crosseye/json-convert/engine/prepare.js'
)
const { mergeRecordShapes } = require(
  '$:/plugins/crosseye/json-convert/engine/shape.js'
)
const {
  serializeShape, compareShapes, isMismatch, topLevelFields,
  profilePaths, relevantDiff
} = require('$:/plugins/crosseye/json-convert/engine/shape-diff.js')
const { stampFields } = require(
  '$:/plugins/crosseye/json-convert/engine/validate.js'
)
const {
  clearByPrefix, collectUserTransforms, explainTransformErrors
} = require('./util.js')

const DEFAULT_STATE_BASE  = '$:/state/json-convert'
const DEFAULT_STAGED_BASE = '$:/temp/json-convert/staged'

const setJson = (wiki, title, value) => wiki.addTiddler({
  title,
  type: 'application/json',
  text: JSON.stringify(value)
})

const loadProfile = (wiki, profileTitle) => {
  if (!profileTitle) {
    return {
      error: {
        code: 'no-profile-selected',
        message: 'No profile selected'
      }
    }
  }
  const text = wiki.getTiddlerText(profileTitle) || ''
  try {
    return { profile: JSON.parse(text) }
  } catch (e) {
    return {
      error: {
        code: 'profile-not-json',
        message:
          `Profile "${profileTitle}" is not valid JSON: ${e.message}`
      }
    }
  }
}

// `_stamp` carries the profile's stamp list to Apply, which is where
// the dates are taken, so a staged tiddler shows what the profile
// produced and nothing else.
const writeStaged = (wiki, stagedPrefix, tiddlers, collisions, stamps) =>
  tiddlers.forEach((t, i) => {
    const fields = {
      ...t,
      title: `${stagedPrefix}${i}`,
      '_target-title': t.title
    }
    if (collisions.has(t.title)) fields._collision = 'yes'
    if (stamps.length) fields._stamp = $tw.utils.stringifyList(stamps)
    wiki.addTiddler(fields)
  })

const COLLISION_DEFAULTS = new Set(['skip', 'overwrite'])

const writeDecisions =
  (wiki, decisionsPrefix, tiddlers, collisions, collisionDefault) =>
  tiddlers.forEach((t, i) => {
    const action = collisions.has(t.title) ? collisionDefault : 'add'
    wiki.addTiddler({ title: `${decisionsPrefix}${i}`, text: action })
  })

// Compare the shape of the records actually found with the shape the
// pack was built against (its `shape` tiddler), so the panel can say
// which fields the importer expected and did not see.  Written only
// when the source parsed and a fingerprint is available.
const writeShapeCheck = (wiki, stateBase, shapeTitle, source, profile) => {
  const title = `${stateBase}/result/shape`
  wiki.deleteTiddler(title)
  if (!shapeTitle || !profile) return
  let expected
  try {
    expected = JSON.parse(wiki.getTiddlerText(shapeTitle) || '')
  } catch (_) {
    return
  }
  if (!expected || !expected.shape) return
  const prepared = prepareSource(source, profile.normalize)
  if (prepared.errors.length) return
  const expanded = expandRecords(prepared.value, profile.records)
  const records = expanded.records
    ? expanded.records.map((r) => r.record)
    : []
  const actual = records.length
    ? serializeShape(mergeRecordShapes(records))
    : null
  const diff = actual
    ? relevantDiff(compareShapes(expected.shape, actual), profilePaths(profile))
    : { missing: [], added: [], changed: [] }
  setJson(wiki, title, {
    expected: {
      records: expected.records,
      count: expected.count,
      fields: topLevelFields(expected.shape)
    },
    actual: { count: records.length, fields: topLevelFields(actual) },
    ...diff,
    mismatch: isMismatch(diff)
  })
}

const writeResults = (wiki, stateBase, result) => {
  setJson(wiki, `${stateBase}/result/errors`, result.errors)
  setJson(wiki, `${stateBase}/result/warnings`, result.warnings)
  setJson(wiki, `${stateBase}/result/collisions`, [...result.collisions])
}

// `sourceTitle` names the tiddler holding the JSON text; `profileTitle`
// names the profile itself.  Both default to conventional tiddlers under
// the state base, the latter indirectly: `<state-base>/profile` holds the
// title of the selected profile, which is how a picker-driven panel
// works.  A panel with a fixed profile passes it directly.
const runConversion = (
  wiki, stateBase, stagedBase, sourceTitle, profile, collisionDefault,
  shapeTitle
) => {
  const stagedPrefix    = `${stagedBase}/`
  const decisionsPrefix = `${stateBase}/decisions/`
  clearByPrefix(wiki, stagedPrefix)
  clearByPrefix(wiki, decisionsPrefix)

  const source = wiki.getTiddlerText(sourceTitle) || ''
  const profileTitle =
    profile || wiki.getTiddlerText(`${stateBase}/profile`) || ''
  const loaded = loadProfile(wiki, profileTitle)

  const userTransforms = collectUserTransforms(wiki)
  const result = loaded.error
    ? {
        tiddlers: [],
        errors: [loaded.error],
        warnings: [],
        collisions: new Set()
      }
    : convert(
        source,
        loaded.profile,
        new Set(wiki.allTitles()),
        { transforms: userTransforms }
      )

  result.errors = explainTransformErrors(wiki, result.errors)
  writeShapeCheck(wiki, stateBase, shapeTitle, source, loaded.profile)
  writeStaged(
    wiki, stagedPrefix, result.tiddlers, result.collisions,
    loaded.profile ? stampFields(loaded.profile) : []
  )
  writeDecisions(
    wiki, decisionsPrefix, result.tiddlers, result.collisions,
    collisionDefault
  )
  writeResults(wiki, stateBase, result)
}

const JsonConvertRunWidget = function(parseTreeNode, options) {
  this.initialise(parseTreeNode, options)
}

JsonConvertRunWidget.prototype = Object.create(Widget.prototype)

JsonConvertRunWidget.prototype.render = function(parent, nextSibling) {
  this.computeAttributes()
  this.execute()
}

JsonConvertRunWidget.prototype.execute = function() {
  this.stateBase = this.getAttribute('state-base', DEFAULT_STATE_BASE)
  this.stagedBase = this.getAttribute('staged-base', DEFAULT_STAGED_BASE)
  this.sourceTitle =
    this.getAttribute('source-title', `${this.stateBase}/source`)
  this.profile = this.getAttribute('profile', '')
  const collisionDefault = this.getAttribute('collision-default', 'skip')
  this.collisionDefault =
    COLLISION_DEFAULTS.has(collisionDefault) ? collisionDefault : 'skip'
  this.shapeTitle = this.getAttribute('shape-title', '')
}

JsonConvertRunWidget.prototype.refresh = function(changedAttributes) {
  const changed = this.computeAttributes()
  if (changed['state-base'] || changed['staged-base'] ||
      changed['source-title'] || changed['profile'] ||
      changed['collision-default'] || changed['shape-title']) {
    this.refreshSelf()
    return true
  }
  return false
}

JsonConvertRunWidget.prototype.invokeAction = function() {
  runConversion(
    this.wiki, this.stateBase, this.stagedBase, this.sourceTitle,
    this.profile, this.collisionDefault, this.shapeTitle
  )
  return true
}

exports['json-convert-run'] = JsonConvertRunWidget
","type":"application/javascript","module-type":"widget"},"$:/plugins/crosseye/json-convert/widgets/source-status.js":{"title":"$:/plugins/crosseye/json-convert/widgets/source-status.js","text":"const Widget = require('$:/core/modules/widgets/widget.js').widget
const { parse } = require(
  '$:/plugins/crosseye/json-convert/engine/parser.js'
)

// Live verdict on the source JSON, rendered under the source box.
// Without it a malformed paste is indistinguishable from a successful
// run that produced nothing: Convert reports `parse-failed` into a
// collapsed panel and the staging area simply stays empty.
//
//   <$json-convert-source-status source-title=<<t>> note-title=<<n>>/>

const MAX_EXCERPT = 120

// Keep the caret next to the offending column on a very long line.
const windowExcerpt = (excerpt, column) => {
  if (excerpt.length <= MAX_EXCERPT) return { text: excerpt, column }
  const start = Math.max(0, column - Math.floor(MAX_EXCERPT / 2))
  const text = (start > 0 ? '…' : '') +
    excerpt.slice(start, start + MAX_EXCERPT) +
    (start + MAX_EXCERPT < excerpt.length ? '…' : '')
  return { text, column: column - start + (start > 0 ? 1 : 0) }
}

const caretLine = (text, column) => {
  if (column === undefined) return null
  // Tabs in the excerpt would misalign a space-built caret.
  const prefix = text.slice(0, Math.max(0, column - 1))
    .replace(/[^\t]/g, ' ')
  return prefix + '^'
}

function JsonConvertSourceStatusWidget(parseTreeNode, options) {
  this.initialise(parseTreeNode, options)
}

JsonConvertSourceStatusWidget.prototype = Object.create(Widget.prototype)

JsonConvertSourceStatusWidget.prototype.render = function(parent, nextSibling) {
  this.parentDomNode = parent
  this.computeAttributes()
  this.execute()

  const root = this.document.createElement('div')
  root.className = 'jc-source-status'

  const note = this.noteTitle
    ? (this.wiki.getTiddlerText(this.noteTitle) || '').trim()
    : ''
  const text = this.wiki.getTiddlerText(this.sourceTitle) || ''

  if (note) root.appendChild(this.line('jc-source-note', note))

  if (text.trim()) {
    const result = parse(text)
    if (result.errors.length > 0) root.appendChild(this.errorBlock(result.errors[0]))
    else if (result.warnings.length > 0) {
      root.appendChild(this.line('jc-source-warn', result.warnings[0].message))
    } else {
      root.appendChild(this.line('jc-source-ok', 'Valid JSON.'))
    }
  }

  parent.insertBefore(root, nextSibling)
  this.domNodes.push(root)
}

JsonConvertSourceStatusWidget.prototype.line = function(cls, message) {
  const node = this.document.createElement('div')
  node.className = cls
  node.textContent = message
  return node
}

JsonConvertSourceStatusWidget.prototype.errorBlock = function(err) {
  const box = this.document.createElement('div')
  box.className = 'jc-source-err'

  const heading = this.document.createElement('div')
  heading.className = 'jc-source-err-heading'
  heading.textContent = err.message
  box.appendChild(heading)

  if (err.excerpt !== undefined && err.excerpt !== '') {
    const { text, column } = windowExcerpt(err.excerpt, err.column)
    const caret = caretLine(text, column)
    const pre = this.document.createElement('pre')
    pre.className = 'jc-source-err-excerpt'
    pre.textContent = caret === null ? text : `${text}\n${caret}`
    box.appendChild(pre)
  }

  const hint = this.document.createElement('div')
  hint.className = 'jc-source-err-hint'
  hint.textContent =
    'Nothing can be converted until this is fixed.  A stray character ' +
    'on the line above is the usual cause.'
  box.appendChild(hint)

  return box
}

JsonConvertSourceStatusWidget.prototype.execute = function() {
  this.sourceTitle = this.getAttribute('source-title', '')
  this.noteTitle = this.getAttribute('note-title', '')
}

JsonConvertSourceStatusWidget.prototype.refresh = function(changedTiddlers) {
  const changedAttributes = this.computeAttributes()
  // A note ("Loaded from dropped file…", "Loaded the sample…") describes
  // how the current text arrived.  Whoever writes it changes the source
  // and the note together; a change to the source alone is the user
  // editing, and the note no longer applies.
  if (this.noteTitle && this.sourceTitle &&
      changedTiddlers[this.sourceTitle] && !changedTiddlers[this.noteTitle] &&
      this.wiki.tiddlerExists(this.noteTitle)) {
    this.wiki.deleteTiddler(this.noteTitle)
  }
  if (changedAttributes['source-title'] ||
      changedAttributes['note-title'] ||
      (this.sourceTitle && changedTiddlers[this.sourceTitle]) ||
      (this.noteTitle && changedTiddlers[this.noteTitle])) {
    this.refreshSelf()
    return true
  }
  return false
}

exports['json-convert-source-status'] = JsonConvertSourceStatusWidget
